import styled from "styled-components";
import { NavLink } from "react-router-dom";
import { User } from "lucide-react"; 
import { useState, useEffect } from "react";
import { useDispatch, useSelector } from "react-redux";
import { logout } from "../redux/userSlice"; // Import the logout action

// Styles for components
const Container = styled.div`
  position: sticky;
  top: 0;
  background-color: #f0f0f0;
  height: 56px;
  z-index: 1;
`;

const Wrapper = styled.div`
  display: flex;
  align-items: center;
  height: 100%;
  padding: 0px 20px;
  justify-content: flex-end;
  position: relative;
  width: 90%;
`;

const Button = styled.button`
  padding: 5px 15px;
  background-color: transparent;
  border: none;
  color: ${({ isActive }) => (isActive ? "black" : "#59595e")};
  font-weight: ${({ isActive }) => (isActive ? 500 : 400)};
  cursor: pointer;

  &:hover {
    color: ${({ isActive }) => (isActive ? "black" : "#29292b")};
  }
`;

const UserIcon = styled(User)`
  width: 30px;
  height: 30px;
  color: #59595e;
  cursor: pointer;
  margin-left: 30px;
  &:hover {
    color: #29292b;
  }
`;

// Dropdown and modal styles
const DropdownMenu = styled.div`
  position: absolute;
  top: 50px;
  right: 0;
  background-color: white;
  border: 1px solid #ddd;
  box-shadow: 0 4px 6px rgba(0, 0, 0, 0.1);
  display: ${({ show }) => (show ? "block" : "none")};
  padding: 10px;
  border-radius: 4px;
`;

const DropdownItem = styled.div`
  padding: 10px;
  cursor: pointer;
  &:hover {
    background-color: #f0f0f0;
  }
`;

const ModalBackground = styled.div`
  position: fixed;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  background-color: rgba(0, 0, 0, 0.3);
  display: ${({ show }) => (show ? "flex" : "none")};
  justify-content: center;
  align-items: center;
`;

const Modal = styled.div`
  background-color: white;
  padding: 20px;
  border-radius: 8px;
  text-align: center;
  width: 350px;
  box-shadow: 0 4px 6px rgba(0, 0, 0, 0.2);
  display: flex;
  flex-direction: column;
  align-items: center;

  h3 {
    margin-bottom: 20px;
    font-size: 18px;
    font-weight: bold;
  }

  button {
    padding: 8px 16px;
    margin: 5px;
    cursor: pointer;
    border-radius: 4px;
    border: 1px solid #ddd;
    background-color: #f0f0f0;
    transition: background-color 0.3s;

    &:hover {
      background-color: #ddd;
    }

    &:first-child {
      background-color: #4CAF50;
      color: white;
    }

    &:last-child {
      background-color: #f44336;
      color: white;
    }
  }

  // Flexbox to align buttons horizontally
  .button-container {
    display: flex;
    justify-content: space-between;
    width: 100%;
  }
`;

const Navbar = () => {
  const dispatch = useDispatch();
  const { isLogin } = useSelector((state) => state.user); // Get login status from Redux store
  const [showDropdown, setShowDropdown] = useState(false); // Toggle dropdown
  const [showModal, setShowModal] = useState(false); // Show/Hide logout modal

  const handleLogout = () => {
    setShowModal(true); 
    setShowDropdown(false); 
  };

  const confirmLogout = () => {
    dispatch(logout());
    setShowModal(false);
    window.location.reload(); 
  };

  // Cancel logout
  const cancelLogout = () => {
    setShowModal(false);
  };

  return (
    <Container>
      <Wrapper>
        <NavLink to="/">
          {({ isActive }) => <Button isActive={isActive}>Home</Button>}
        </NavLink>
        <NavLink to="/submit">
          {({ isActive }) => <Button isActive={isActive}>Submit</Button>}
        </NavLink>
        <NavLink to="/jobs">
          {({ isActive }) => <Button isActive={isActive}>Jobs</Button>}
        </NavLink>
        <NavLink to="/view">
          {({ isActive }) => <Button isActive={isActive}>Viewer</Button>}
        </NavLink>

        {/* Conditionally render Login button */}
        {!isLogin && (
          <NavLink to="/login">
            {({ isActive }) => <Button isActive={isActive}>Login</Button>}
          </NavLink>
        )}

        {/* User Icon and Dropdown menu */}
        {isLogin && (
          <>
            <UserIcon onClick={() => setShowDropdown(!showDropdown)} />
            <DropdownMenu show={showDropdown}>
              <DropdownItem onClick={() => alert("View Account Info")}>
                Xem thông tin tài khoản
              </DropdownItem>
              <DropdownItem onClick={handleLogout}>Đăng Xuất</DropdownItem>
            </DropdownMenu>
          </>
        )}
      </Wrapper>

      {/* Modal for logout confirmation */}
      <ModalBackground show={showModal}>
        <Modal>
          <h3>Bạn có chắc chắn muốn đăng xuất?</h3>
          <div className="button-container">
            <button onClick={confirmLogout}>Có</button>
            <button onClick={cancelLogout}>Hủy</button>
          </div>
        </Modal>
      </ModalBackground>
    </Container>
  );
};

export default Navbar;
